e uskuteční v sobotu 19. června 2027.","notes":"Výslovný termín 25. ročníku. Starý záznam nese označení Gravel; oznámení hlavního závodu samo nepotvrzuje konání nové gravelové varianty. Nepřenášet její disciplínu bez ověření."}]}'::jsonb AS doc),
location_input AS (SELECT value AS doc FROM input,jsonb_array_elements(input.doc->'locations')),
new_locations AS (INSERT INTO locations(id,name,municipality,venue,lat,lng,country_code,timezone,geocode_status,geocode_query)
 SELECT gen_random_uuid(),doc->>'name',doc->>'municipality',doc->>'venue',(doc->>'lat')::float8,(doc->>'lng')::float8,doc->>'country_code',doc->>'timezone',doc->>'geocode_status',doc->>'geocode_query' FROM location_input RETURNING *),
plans AS (SELECT value AS doc FROM input,jsonb_array_elements(input.doc->'events')),
payloads AS (SELECT p.doc, (p.doc->'event') || jsonb_build_object('location_id',coalesce((SELECT to_jsonb(l.id) FROM new_locations l JOIN location_input li ON li.doc->>'name'=l.name WHERE li.doc->>'key'=p.doc->>'locationKey'),p.doc->'event'->'location_id')) AS event FROM plans p),
added AS (INSERT INTO events(slug,name,name_normalized,start_date,end_date,location_id,timezone,disciplines,formats,audience,age_categories,age_confidence,status,visibility,website_url,source_kind,level,class_label,series_id,uci_class,event_type,competition_type,season,registration_url,regulations_url,results_url,fingerprint)
 SELECT e.slug,e.name,e.name_normalized,e.start_date,e.end_date,e.location_id,e.timezone,e.disciplines,e.formats,e.audience,e.age_categories,e.age_confidence,e.status,e.visibility,e.website_url,e.source_kind,e.level,e.class_label,e.series_id,e.uci_class,e.event_type,e.competition_type,e.season,e.registration_url,e.regulations_url,e.results_url,e.fingerprint FROM payloads p CROSS JOIN LATERAL jsonb_populate_record(null::events,p.event) e
 WHERE NOT EXISTS(SELECT 1 FROM events held WHERE held.slug=e.slug OR (held.start_date=e.start_date AND held.name_normalized=e.name_normalized AND held.merged_into_id IS NULL)) ON CONFLICT DO NOTHING RETURNING *),
watches AS (INSERT INTO watched_urls(url,kind,status,added_by,notes) SELECT DISTINCT a.website_url,'race','active','manual-announced-edition','Verified 2027 announcement; annual editions remain separate.' FROM added a ON CONFLICT(url) DO UPDATE SET url=EXCLUDED.url RETURNING id,url),
sources AS (INSERT INTO event_sources(event_id,source_url,kind,is_canonical,watched_url_id,external_id) SELECT a.id,p.doc->>'source_url','race',true,w.id,a.slug FROM added a JOIN payloads p ON p.event->>'slug'=a.slug JOIN watches w ON w.url=a.website_url RETURNING id),
dates AS (INSERT INTO event_facts(event_id,field,value,source_url,quote,method,version) SELECT a.id,'start_date',to_jsonb(a.start_date),p.doc->>'source_url',p.doc->>'quote','manual_source_review','announced-edition-publication-v1' FROM added a JOIN payloads p ON p.event->>'slug'=a.slug RETURNING id),
facts AS (INSERT INTO event_facts(event_id,field,value,source_url,quote,method,version) SELECT a.id,'source_evidence',jsonb_build_object('previous_event_id',p.doc->>'previous_id','published',to_jsonb(a),'notes',p.doc->>'notes','inherited_age_confidence',a.age_confidence),p.doc->>'source_url',p.doc->>'quote','manual_source_review','announced-edition-publication-v1' FROM added a JOIN payloads p ON p.event->>'slug'=a.slug RETURNING id)
SELECT jsonb_build_object('added',(SELECT jsonb_agg(jsonb_build_object('id',id,'slug',slug,'name',name,'date',start_date)) FROM added),'sources',(SELECT count(*) FROM sources),'date_facts',(SELECT count(*) FROM dates),'evidence',(SELECT count(*) FROM facts),'new_locations',(SELECT count(*) FROM new_locations)) AS result;